+  try {
+    const { id } = req.params;
+    const { theme, notifications_enabled } = req.body;
+
+    // Check user exists
+    const userResult = await query('SELECT id FROM users WHERE id = $1', [id]);
+    if (userResult.rows.length === 0) {
+      return res.status(404).json({ error: 'User not found' });
+    }
+
+    // Build update set
+    const updates = [];
+    const values = [];
+    let paramIndex = 1;
+
