+  try {
+    const { id } = req.params;
+
+    const result = await query(
+      'DELETE FROM documents WHERE id = $1 RETURNING id',
+      [id]
+    );
+
+    if (result.rows.length === 0) {
+      return res.status(404).json({ error: 'Document not found' });
+    }
